    # Highlight short gaps between aligned markers. Longer spans are separate
    # structure, rather than a missing segment.
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            if 1 < b - a <= 4:
